class Point{

	constructor( x, y, nom='?point?' ){
		this.nom = nom;
		this.x = x;
		this.y = y;
	}

	draw( zoom=1 ){
		let l = zoom/8.33;
		push();
		stroke(0, 0, 0);
		//setLineDash([0]);
		line( this.x*zoom-l, this.y*zoom-l, this.x*zoom+l, this.y*zoom+l );
		line( this.x*zoom-l, this.y*zoom+l, this.x*zoom+l, this.y*zoom-l );
		textSize(zoom*0.3);		// Taille du texte
		fill(0, 0, 0); noStroke();
		text( this.nom ,  this.x*zoom+2*l, this.y*zoom-2*l  );
		pop();
	}

	toString(){
		return "Point(x="+round(this.x)+",y="+round(this.y)+",nom='"+this.nom+"')";
	}
}



// === Tab: Cercle ===
class Cercle{

	constructor( centre, rayon, nom='?cercle?'){
		this.centre = centre;	// un Point
		this.rayon = rayon;
		this.nom = nom;
	}

	draw( zoom=1 ){
		this.centre.draw( zoom );							// Trace le centre du cercle
		push();
//		fill(200, 0, 200);
//		textSize(zoom*0.4);
//		text(this.nom, this.centre.x*zoom, this.centre.y*zoom + this.rayon*zoom - 10 );
		noFill();
		stroke(64, 0, 64);
		strokeWeight(zoom*0.02);
		setLineDash([10, 4]);
		circle( this.centre.x*zoom, this.centre.y*zoom, this.rayon*zoom );
		if(this.rayon>1){
			textSize(zoom*0.3);
			if(this.centre.x>=0){
				let angle=11.8*PI/6;
				setLineDash([5, 2]);
				line( this.centre.x*zoom, this.centre.y*zoom, this.centre.x*zoom + this.rayon*cos(angle)*zoom, this.centre.y*zoom - this.rayon*sin(angle)*zoom);
				translate( this.centre.x*zoom + this.rayon/2*cos(angle)*zoom, this.centre.y*zoom - this.rayon/2*sin(angle)*zoom );
				rotate( -angle);textAlign(CENTER,TOP);
				noStroke();fill(255);text("rayon = "+round(this.rayon,2),0,0);
				textAlign(CENTER,BOTTOM);text(this.nom, 0, 0 );
			}else{
				let angle=6.2*PI/6;
				setLineDash([5, 2]);
				line( this.centre.x*zoom, this.centre.y*zoom, this.centre.x*zoom + this.rayon*cos(angle)*zoom, this.centre.y*zoom - this.rayon*sin(angle)*zoom);
				translate( this.centre.x*zoom + this.rayon/2*cos(angle)*zoom, this.centre.y*zoom - this.rayon/2*sin(angle)*zoom );
				rotate(PI-angle);textAlign(CENTER,TOP);
				noStroke();fill(255);text("rayon = "+round(this.rayon,2),0,0);
				textAlign(CENTER,BOTTOM);text(this.nom, 0, 0 );
			}
		}
		pop();
	}

	toString(){
		return "Cercle("+this.centre.toString()+","+round(this.rayon)+",'"+this.nom+"')";
	}
}


