 passant par les points A et B
 *************************************/
function cerclesPassantPar( A, B, r, nom='x'){
	// Calcul de la distance entre A et B
  let d_AB = dist(A.x, A.y, B.x, B.y);

  // Vérification si un cercle peut exister
  if (d_AB > 2 * r) {
    print("Aucun cercle ne peut passer par A et B avec le rayon donné.");
    return;
  }

  // Calcul du milieu du segment AB
  let M = createVector((A.x + B.x) / 2, (A.y + B.y) / 2);

  // Calcul de la distance entre M et les centres des cercles
  let h = sqrt(sq(r) - sq(d_AB / 2));

  // Vecteur perpendiculaire à AB
  let perp = createVector(-(B.y - A.y), B.x - A.x);
  perp.normalize();

  // Centres des deux cercles
//  let C1 = createVector(M.x + h * perp.x, M.y + h * perp.y);
//  let C2 = createVector(M.x - h * perp.x, M.y - h * perp.y);
	let C1,C2;
	if(nom=='x'){
  	C1 = new Point(M.x + h * perp.x, M.y + h * perp.y ,A.nom+'x'+B.nom);
  	C2 = new Point(M.x - h * perp.x, M.y - h * perp.y ,B.nom+'x'+A.nom);
	}else{
  	C1 = new Point(M.x + h * perp.x, M.y + h * perp.y ,nom);
  	C2 = new Point(M.x - h * perp.x, M.y - h * perp.y ,nom);
	}
	return [C1,C2];
}

