function angleArc( C, A, B ){
	// Points A, B et le centre C

	// Rayon du cercle
  let rayon = dist(A.x, A.y, C.x, C.y); // ou dist(B.x, B.y, C.x, C.y)

  // Calcul du produit scalaire entre CA et CB
  let CA = createVector(A.x - C.x, A.y - C.y);
  let CB = createVector(B.x - C.x, B.y - C.y);

  let dotProduct = CA.x * CB.x + CA.y * CB.y;

  // Calcul de l'angle entre A et B par rapport à C
  let cosTheta = dotProduct / (rayon *rayon);
  let theta = acos(cosTheta); // Angle en radians

  // Calcul de la longueur de l'arc
  let arcLength = rayon * theta;

/*
