	arc(points['d3'].x * zoom, points['d3'].y * zoom, rayon * zoom, rayon * zoom, start, stop);

	[start, stop, rayon] = angleArc(points['d2'], points['i6'], points['e3']);
	arc(points['d2'].x * zoom, points['d2'].y * zoom, rayon * zoom, rayon * zoom, start, stop);

	[start, stop, rayon] = angleArc(points['d0'], points['e4'], points['i7']);
	arc(points['d0'].x * zoom, points['d0'].y * zoom, rayon * zoom, rayon * zoom, start, stop);

	[start, stop, rayon] = angleArc(points['d3'], points['i8'], points['e4']);
	arc(points['d3'].x * zoom, points['d3'].y * zoom, rayon * zoom, rayon * zoom, start, stop);

	//-------------------------- Pommelots
	fill('#FDDD00');
	stroke('#FDDD00');
	for (i = 0; i < 12; i++) {
		circle(cercles['C' + i].centre.x * zoom, cercles['C' + i].centre.y * zoom, cercles['C' + i].rayon * zoom);
	}
	pop();

	if (trace) {
		// Trace les cercles
		for (key in cercles) {
			cercles[key].draw(zoom);
		}

		// Trace les points
		for (key in points) {
			points[key].draw(zoom);
		}
		// trace les axes X et Y
		push();
		setLineDash([20, 5, 2, 5]);
		noFill();
		stroke(0);
		strokeWeight(1.5); // Default
		line(-24 * zoom, 0, 24 * zoom, 0); // Axe X
		line(0, -24 * zoom, 0, 24 * zoom); // Axe Y
		pop();
	}
}
