function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	//	background(0);
	avance = 0;
}

function keyPressed() {
	if (key.toUpperCase() == 'F') {
		fullscreen(!createCanvas(windowWidth, windowHeight, WEBGL));
	} else if (key.toUpperCase() == ' ') {
		avance = 0;
	} else if (key.toUpperCase() == 'T') {
		trace = !trace;
	} else if (key.toUpperCase() == 'S') {
		save("Croix_occitane" + round(rayons[0]) + '-' + round(rayons[1]) + '-' + round(rayons[2]) + '-' + round(rayons[3]) + ".jpg");
	} else help = !help;
}
